/**
 * The wire contract — NOT to be confused with `apps/api/src/contracts/`.
 *
 *   apps/api/src/contracts/   in-process PORT surface (entitlement.port, notification.port,
 *                             events). Consumed by modules/**. Enforces DR-1.
 *   packages/contracts        this package: the OpenAPI-generated client and shared DTOs.
 *                             Consumed by apps/web and apps/admin. Never by apps/api —
 *                             the API produces it, so importing it would be a cycle.
 *
 * openapi/v1.json is generated by `pnpm --filter @easyesg/api openapi:emit` and committed.
 * `src/generated/v1.ts` is generated from it by `pnpm --filter @easyesg/contracts generate`
 * (openapi-typescript, types only — no runtime). CI regenerates and diffs BOTH in the same
 * gate: a PR that changes a route must commit the regenerated spec and types (P-5, NFR-83).
 *
 * The aliases below are the package's public surface. Consumers import these names rather than
 * indexing `components['schemas'][…]` at every call site — the indexing is the generated file's
 * concern, and keeping it here means a renamed schema breaks one line, not every screen.
 */
import type { components } from './generated/v1';

export type { paths, operations, components } from './generated/v1';
export {
  PROBLEM_CONTENT_TYPE,
  PROBLEM_TYPE,
  type ProblemDocument,
  type ProblemTypeUri,
} from './problem';
export type { Message, ResultList, ResultObject } from './envelope';
export {
  API_OUTCOME,
  mapOutcome,
  readProblemDocument,
  readResultList,
  readResultObject,
  type ApiFailure,
  type ApiOutcome,
  type ApiOutcomeStatus,
  type ListResult,
} from './outcome';

// identity — /api/v1/auth (FR-1, FR-3; task 19)
export { ACCOUNT_STATUS, type AccountStatus } from './account';
export type RegisterAccountRequest = components['schemas']['RegisterAccountRequestDto'];
export type VerifyEmailRequest = components['schemas']['VerifyEmailRequestDto'];
export type ResendVerificationEmailRequest =
  components['schemas']['ResendVerificationEmailRequestDto'];
export type AccountResponse = components['schemas']['AccountResponseDto'];

// identity — sessions and password reset (FR-4, FR-5, FR-6; task 21)
export type SignInRequest = components['schemas']['SignInRequestDto'];
export type RefreshSessionRequest = components['schemas']['RefreshSessionRequestDto'];
export type SignOutRequest = components['schemas']['SignOutRequestDto'];
export type SessionResponse = components['schemas']['SessionResponseDto'];
export type SessionAccount = components['schemas']['SessionAccountDto'];
export type RequestPasswordResetRequest =
  components['schemas']['RequestPasswordResetRequestDto'];
export type ResetPasswordRequest = components['schemas']['ResetPasswordRequestDto'];

// identity — the second factor at sign-in (UC-194, UC-195; task 27.3). `POST /auth/session` answers
// one of TWO shapes, discriminated by `kind` — see `SIGN_IN_OUTCOME` in `social.ts`; a client that
// probes for `accessToken` instead has written the discriminator twice.
export type FactorChallengeResponse = components['schemas']['FactorChallengeResponseDto'];
export type CompleteFactorRequest = components['schemas']['CompleteFactorRequestDto'];

// identity — managing the second factor and the linked providers, S-28's reads (UC-11 … UC-12,
// UC-193; tasks 27.2, 27.6). Added 27 Aug 2026: `apps/web` was restating both of these by hand,
// and the copy of `LinkedProviderResponseDto` had widened `provider` from the contract's own
// two-member enum to `string` — which is the drift this package exists to make impossible, and it
// let an unrecognised provider slug reach a rendered sentence.
export type TotpState = components['schemas']['TotpStateResponseDto'];
export type LinkedProvider = components['schemas']['LinkedProviderResponseDto'];

// identity — memberships and members (FR-12, FR-56 … FR-60; tasks 25.2, 25.3). Two shapes and not
// one: `Member` is a person in THIS organization, read with a tenant bound; `AccountMembership` is
// an organization the CALLER belongs to, read before any tenant exists. They never appear together.
export {
  INVITED_ROLE,
  MEMBERSHIP_ROLE,
  MEMBERSHIP_STATUS,
  type InvitedRole,
  type MembershipRole,
  type MembershipStatus,
} from './membership';
export type Member = components['schemas']['MemberResponseDto'];
export type ChangeMemberRoleRequest = components['schemas']['ChangeMemberRoleRequestDto'];
export type AccountMembership = components['schemas']['AccountMembershipResponseDto'];

// identity — invitations (FR-11, FR-57; tasks 26.1, 26.2). Two audiences on one resource, which is
// why the shapes do not overlap: `Invitation` is a row on the administrator's list, read with a
// tenant bound; the preview and acceptance shapes belong to the **bearer** of a link, who may hold
// no session at all. `InvitationTokenRequest` is the body of both bearer routes — the token travels
// in a POST body rather than a URL so it stays out of access logs and referrer headers.
export {
  INVITATION_STANDING,
  MEMBERSHIP_GRANT_KIND,
  type InvitationStanding,
  type MembershipGrantKind,
} from './invitation';
export type Invitation = components['schemas']['InvitationResponseDto'];
export type IssueInvitationRequest = components['schemas']['IssueInvitationRequestDto'];
export type InvitationTokenRequest = components['schemas']['InvitationTokenRequestDto'];
export type InvitationPreview = components['schemas']['InvitationPreviewResponseDto'];
export type AcceptedInvitation = components['schemas']['AcceptedInvitationResponseDto'];

// identity — /api/v1/auth/social (FR-2, FR-4, FR-82; task 24). The OAuth transaction — state,
// nonce, verifier — travels through apps/web's sealed transaction cookie, never readable in the
// browser; these shapes are the back-channel surface between the web tier and the api.
export {
  SOCIAL_PROVIDER,
  SIGN_IN_OUTCOME,
  SOCIAL_SIGN_IN_INTENT,
  isSocialProvider,
  isSocialSignInIntent,
  type SocialProvider,
  type SocialSignInIntent,
} from './social';
export type SocialChallengeRequest = components['schemas']['SocialChallengeRequestDto'];
export type SocialChallengeResponse = components['schemas']['SocialChallengeResponseDto'];
export type CompleteSocialSignInRequest =
  components['schemas']['CompleteSocialSignInRequestDto'];
export type SocialProvidersResponse = components['schemas']['SocialProvidersResponseDto'];

// platform — /api/v1/auth/admin (FR-75; task 23, the two-step handshake since 24 Aug 2026).
// The challenge and the session travel as sealed httpOnly cookies the api sets — these shapes
// are the BODY surface only; tokens and the challenge deliberately absent.
export type AdminChallengeRequest = components['schemas']['AdminChallengeRequestDto'];
export type AdminChallengeResponse = components['schemas']['AdminChallengeResponseDto'];
export type AdminFactorRequest = components['schemas']['AdminFactorRequestDto'];
export type AdminSessionResponse = components['schemas']['AdminSessionResponseDto'];
export type AdminAccount = components['schemas']['AdminAccountDto'];
